<!DOCTYPE html><html lang="id"><head><meta charset="utf-8"><title>{{ $order->order_number }}</title>@vite(['resources/js/app.js'])<style>@page{size:58mm auto;margin:2mm}*{box-sizing:border-box}body{width:54mm;margin:0 auto;font:12px/1.4 monospace;color:#111}.center{text-align:center}.line{border-top:1px dashed #111;margin:8px 0}.row{display:flex;justify-content:space-between;gap:10px}.item{margin-bottom:5px}.small{font-size:10px}.bold{font-weight:bold}.total{font-size:15px;font-weight:bold}.no-print{margin:12px 0;width:100%;padding:10px;background:#f5f5f4;border:1px solid #d6d3d1;border-radius:8px}.receipt-actions button{display:block;width:100%;margin:6px 0;padding:10px;border:0;border-radius:6px;background:#111;color:#fff;font-weight:bold}.receipt-actions button:first-child{background:#ea580c}.receipt-actions p{margin:8px 0 0;font:11px/1.4 sans-serif}@media print{.no-print{display:none}}</style></head><body><div class="center"><h2 style="margin:0">{{ $store->store_name }}</h2><div class="small">{{ $store->address }}</div><div class="small">{{ $store->phone }}</div></div><div class="line"></div><div class="row"><span>Order</span><b>{{ $order->order_number }}</b></div><div class="row"><span>Waktu</span><span>{{ $order->paid_at?->format('d/m/Y H:i') }}</span></div><div class="row"><span>Kasir</span><span>{{ $order->cashier->name }}</span></div><div class="row"><span>Tipe</span><span>{{ $order->order_type->value }}</span></div><div class="row"><span>Meja</span><b>{{ $order->table_number }}</b></div><div class="row"><span>Atas nama</span><b>{{ $order->customer_name }}</b></div><div class="line"></div>@foreach($order->items as $item)<div class="item"><div class="row"><span>{{ $item->quantity }}x {{ $item->product_name_snapshot }}</span><span>{{ number_format($item->line_total,0,',','.') }}</span></div>@if($item->variant_name_snapshot)<div class="small">+ {{ $item->variant_name_snapshot }}</div>@endif @foreach($item->modifiers as $modifier)<div class="small">+ {{ $modifier->name_snapshot }} ({{ number_format($modifier->price_adjustment,0,',','.') }})</div>@endforeach @if($item->notes)<div class="small">Catatan: {{ $item->notes }}</div>@endif</div>@endforeach<div class="line"></div><div class="row"><span>Subtotal</span><span>{{ number_format($order->subtotal,0,',','.') }}</span></div><div class="row"><span>Diskon</span><span>-{{ number_format($order->discount_total,0,',','.') }}</span></div><div class="row"><span>Pajak</span><span>{{ number_format($order->tax_total,0,',','.') }}</span></div><div class="row"><span>Service</span><span>{{ number_format($order->service_charge_total,0,',','.') }}</span></div><div class="line"></div><div class="row total"><span>TOTAL</span><span>Rp {{ number_format($order->grand_total,0,',','.') }}</span></div><div class="row"><span>{{ $order->payment->method->value }}</span><span>{{ number_format($order->payment->received_amount,0,',','.') }}</span></div><div class="row"><span>Kembali</span><span>{{ number_format($order->payment->change_amount,0,',','.') }}</span></div><div class="line"></div><p class="center small">{{ $store->receipt_footer }}</p><div class="no-print receipt-actions"><button type="button" id="connect-thermal">Hubungkan RPP02N</button><button type="button" id="print-thermal">Cetak Bluetooth</button><button type="button" id="print-browser">Cetak Browser</button><p id="thermal-status" role="status">Printer belum terhubung.</p></div><script type="application/json" id="receipt-transaction">@json($thermalTransaction)</script><script type="module">
const transaction=JSON.parse(document.getElementById('receipt-transaction').textContent);const status=document.getElementById('thermal-status');const setStatus=(message,error=false)=>{status.textContent=message;status.style.color=error?'#b91c1c':'#166534'};document.getElementById('connect-thermal').addEventListener('click',async()=>{setStatus('Mencari printer…');try{const state=await window.KopiPOSThermal.requestAndConnect();setStatus(`Terhubung: ${state.name||'RPP02N'}`)}catch(error){setStatus(error.message,true)}});document.getElementById('print-thermal').addEventListener('click',async()=>{setStatus('Mengirim struk…');try{await window.KopiPOSThermal.printReceipt(transaction);setStatus('Struk berhasil dicetak.')}catch(error){setStatus(error.message,true)}});document.getElementById('print-browser').addEventListener('click',()=>window.print());window.addEventListener('thermal-printer-state',event=>setStatus(event.detail.message,event.detail.connected===false));if(!window.KopiPOSThermal?.supportsWebBluetooth()){setStatus('Web Bluetooth tidak tersedia. Gunakan Chrome/Edge lewat HTTPS.',true)}else{setStatus('Memeriksa printer tersimpan…');window.KopiPOSThermal.reconnectRememberedPrinter().then(state=>setStatus(state?`Terhubung otomatis: ${state.name||'RPP02N'}`:'Printer belum diizinkan untuk situs ini. Tekan Hubungkan RPP02N sekali.')).catch(error=>setStatus(error.message,true))}
</script></body></html>